import Testing
import Foundation
@testable import IrisKit

/// A file that says "Generated by <script>" must point at a script that exists (#884): the price
/// snapshot named one that was never committed, so its own instruction ("rerun the script") could not
/// be followed. Paths resolve from this file, not the working directory.
@Suite("Generated files name a script that exists (#884)")
struct GeneratedHeaderTests {
    private static let repoRoot = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()

    /// Every `Generated by scripts/<name>` header in `Sources`, as (file relative to the repo, script path).
    static func headers(in sources: URL = repoRoot.appendingPathComponent("Sources")) -> [(file: String, script: String)] {
        guard let walker = FileManager.default.enumerator(at: sources, includingPropertiesForKeys: nil) else { return [] }
        var found: [(String, String)] = []
        for case let url as URL in walker where url.pathExtension == "swift" {
            guard let text = try? String(contentsOf: url, encoding: .utf8) else { continue }
            for line in text.split(separator: "\n", omittingEmptySubsequences: true) where line.hasPrefix("//") {
                guard let range = line.range(of: "Generated by scripts/") else { continue }
                let script = "scripts/" + line[range.upperBound...].prefix { $0.isLetter || $0.isNumber || "_-./".contains($0) }
                found.append((url.path.replacingOccurrences(of: repoRoot.path + "/", with: ""), script))
            }
        }
        return found
    }

    @Test func everyGeneratedHeaderNamesAScriptThatIsInTheTree() {
        let found = Self.headers()
        #expect(found.contains { $0.file.hasSuffix("ModelPriceSnapshot.swift") }, "the scan must see the price snapshot's header: \(found)")
        for (file, script) in found {
            let trimmed = script.hasSuffix(".") ? String(script.dropLast()) : script
            #expect(FileManager.default.fileExists(atPath: Self.repoRoot.appendingPathComponent(trimmed).path),
                    "\(file) says it is generated by \(trimmed), which is not in the tree")
        }
    }

    @Test func theScanFindsAMissingScript() throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("gen-header-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }
        try "// Generated by scripts/no-such-script.py on 2026-01-01. Do not edit.\nenum X {}\n".write(
            to: dir.appendingPathComponent("X.swift"), atomically: true, encoding: .utf8)
        let found = Self.headers(in: dir)
        #expect(found.count == 1 && found[0].script.hasPrefix("scripts/no-such-script.py"))
        #expect(!FileManager.default.fileExists(atPath: Self.repoRoot.appendingPathComponent("scripts/no-such-script.py").path))
    }

    @Test func thePriceSnapshotIsPinnedToTheCommitTheScriptNames() throws {
        let script = try String(contentsOf: Self.repoRoot.appendingPathComponent("scripts/gen-model-prices.py"), encoding: .utf8)
        let line = try #require(script.split(separator: "\n").first { $0.hasPrefix("PINNED_COMMIT = ") })
        let commit = line.split(separator: "\"").dropFirst().first.map(String.init) ?? ""
        #expect(commit.count == 40)
        let first = try #require(try String(contentsOf: Self.repoRoot.appendingPathComponent("Sources/IrisKit/ModelPriceSnapshot.swift"),
                                            encoding: .utf8).split(separator: "\n").first)
        #expect(first.contains("/\(commit)/") && first.contains("on \(ModelPriceSnapshot.asOf)"),
                "the snapshot's header must name the script's pinned commit and its date: \(first)")
    }
}
